-- State transitions declared for DigestDigest: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION digest.digest_digests_state_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."state" IS DISTINCT FROM OLD."state" AND NOT (
           (COALESCE(OLD."state"::text, ''), COALESCE(NEW."state"::text, '')) IN (('activated', 'activated'), ('activated', 'deactivated'), ('deactivated', 'activated'), ('deactivated', 'deactivated'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: digest_digests.state % -> %', OLD."state", NEW."state"
            USING ERRCODE = 'check_violation', COLUMN = 'state', CONSTRAINT = 'tg_digest_digests__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS digest_digests_state_transition_check ON digest.digest_digests;
CREATE TRIGGER digest_digests_state_transition_check
    BEFORE UPDATE OF "state" ON digest.digest_digests
    FOR EACH ROW EXECUTE FUNCTION digest.digest_digests_state_transition_check();
